def levenshtein(source, target):
    # Use a dictionary to store calculated distances
    memo = {}

    def recurse(src, tgt):
        if (src, tgt) in memo:
            return memo[(src, tgt)]

        if src == '' or tgt == '':
            result = len(src) or len(tgt)

        elif src[0] == tgt[0]:
